    var def='<circle cx="14" cy="14" r="9" fill="none" stroke="'+c+'" stroke-width="1.2"/><line x1="14" y1="5" x2="14" y2="23" stroke="'+c+'" stroke-width="1"/><line x1="5" y1="14" x2="23" y2="14" stroke="'+c+'" stroke-width="1"/>';
    return s[r]||def;
  }

  function pStat(){
    var hp=d.hp||{cur:0,max:100};var mp=d.mana||{cur:0,max:100};
    var hpP=pct(hp.cur,hp.max);var mpP=pct(mp.cur,mp.max);
    var rows=[[T('nm'),d.name],[T('ag'),d.age],[T('gd'),d.gender],[T('rg'),d.region],[T('bg'),d.background],[T('gl'),d.goal]];
    var gh='';
    rows.forEach(function(r,i){
      gh+='<div class="icard'+(i>=4?' full':'')+'"><div class="icard-l">'+esc(r[0])+'</div><div class="icard-v">'+esc(r[1]||'—')+'</div></div>';
    });
    var conds=d.conditions||[];var injs=d.injuries||[];
    var cb='';
    if(!conds.length&&!injs.length){cb='<span class="badge empty">'+esc(T('norm'))+'</span>';}
    else{
      conds.forEach(function(c){cb+='<span class="badge condition">'+esc(c)+'</span>';});
      injs.forEach(function(c){cb+='<span class="badge injury">⚠ '+esc(c)+'</span>';});
    }
    return '<div class="igrid">'+gh+'</div>'+
      '<div class="sec">'+T('vital')+'</div>'+
      '<div class="bars">'+
        '<div class="bar-row"><div class="bar-label">'+T('hp')+'</div><div class="bar-track"><div class="bar-fill bar-hp" style="width:'+hpP+'%"></div></div><div class="bar-val">'+esc(hp.cur)+'/'+esc(hp.max)+'</div></div>'+
        '<div class="bar-row"><div class="bar-label">'+T('mp')+'</div><div class="bar-track"><div class="bar-fill bar-mp" style="width:'+mpP+'%"></div></div><div class="bar-val">'+esc(mp.cur)+'/'+esc(mp.max)+'</div></div>'+
      '</div>'+
      '<div class="sec">'+T('cond')+'</div>'+
      '<div class="badges">'+cb+'</div>';
  }

  function pSkills(){
    var ab=d.abilities||[];
    if(!ab.length)return '<div class="empty-state">'+esc(T('no_ab'))+'</div>';
    return '<div class="sec">'+T('skills')+'</div>'+ab.map(function(a){
      var rk=a.rank||'D';
      return '<div class="ab-card"><div class="rank-badge rank-'+rk+'">'+esc(rk)+'</div><div><div class="ab-name">'+esc(a.name)+'</div><div class="ab-desc">'+esc(a.desc)+'</div></div></div>';
    }).join('');
  }

  function pItems(){
    var inv=d.inventory||[];
    if(!inv.length)return '<div class="sec">'+T('inv')+'</div><div class="empty-state">'+esc(T('no_inv'))+'</div>';
    var gr={};var order=[];
    inv.forEach(function(it){var tp=it.type||'Other';if(!gr[tp]){gr[tp]=[];order.push(tp);}gr[tp].push(it);});
    var h='<div class="sec">'+T('inv')+'</div>';
    order.forEach(function(tp){
      h+='<div class="inv-group"><div class="inv-type-label">'+esc(tp)+'</div>';
      gr[tp].forEach(function(it){
        h+='<div class="inv-item"><div class="inv-qty">×'+esc(it.qty||1)+'</div><div class="inv-info"><div class="inv-name">'+esc(it.name)+'</div>'+(it.desc?'<div class="inv-desc">'+esc(it.desc)+'</div>':'')+'</div></div>';
      });
      h+='</div>';
    });
    return h;
  }

  function pGear(){
    var eq=d.equipment||[];
    var h='<div class="sec">'+T('eq')+'</div>';
    if(!eq.length)return h+'<div class="empty-state">'+esc(T('no_gear'))+'</div>';
    var sm={};eq.forEach(function(e){sm[e.slot]=e;});
    ['Main Hand','Off Hand','Armor','Head','Feet','Accessory'].forEach(function(sl){
      var e=sm[sl];
      var cnt=e?'<div class="eq-name">'+esc(e.name)+'<span class="eq-cond cond-'+(e.condition||'good')+'">'+esc(e.condition||'good')+'</span></div>'+(e.desc?'<div class="eq-desc">'+esc(e.desc)+'</div>':''):'<div class="eq-empty">—</div>';
      h+='<div class="eq-slot"><div class="eq-slot-label">'+esc(sl)+'</div><div class="eq-slot-line"></div><div class="eq-item">'+cnt+'</div></div>';
    });
    return h;
  }

  function pCraft(){
    var inv=d.inventory||[];
    var selTxt=sel.length?sel.map(function(i){var it=inv[i];return it?it.name+' ×'+(it.qty||1):'?';}).join(' + '):T('none');
    var hasItems=sel.length>0;
    var pillsH=inv.length?inv.map(function(it,i){
      return '<div class="craft-pill'+(sel.indexOf(i)>=0?' selected':'')+'" data-idx="'+i+'">'+esc(it.name)+' <span class="pill-qty">×'+esc(it.qty||1)+'</span></div>';
    }).join(''):'<span class="badge empty">'+esc(T('no_craf'))+'</span>';
    return '<div class="sec">'+T('cr')+'</div>'+
      '<div class="craft-lbl">'+esc(T('ing'))+'</div>'+
      '<div class="craft-pills">'+pillsH+'</div>'+
      '<div class="craft-lbl">'+esc(T('sel_lbl'))+'</div>'+
      '<div class="craft-sel-box'+(hasItems?' has-items':'')+'">'+esc(selTxt)+'</div>'+
      '<textarea class="craft-intent" rows="2" placeholder="'+esc(T('iph'))+'"></textarea>'+
      '<button class="btn-craft">'+esc(T('cbtn'))+'</button>';
  }

  function pLog(){
    var rc=d.recipes||[];
    var h='<div class="sec">'+T('lg')+'</div>';
    if(!rc.length)return h+'<div class="empty-state">'+esc(T('no_rec'))+'</div>';
    return h+rc.map(function(r){
      return '<div class="recipe-card">'+
        '<div class="recipe-hdr"><div class="recipe-name">'+esc(r.name)+'</div><span class="recipe-q q-'+(r.quality||'ok')+'">'+esc(r.quality||'ok')+'</span><button class="btn-del" data-rid="'+esc(r.id)+'" data-rname="'+esc(r.name)+'">'+T('del')+'</button></div>'+
        '<div class="recipe-ingr">'+esc(T('ilbl'))+' '+esc((r.ingredients||[]).join(', '))+'</div>'+
        '<div class="recipe-result">'+esc(T('rlbl'))+' '+esc(r.result||'—')+'</div>'+
        (r.notes?'<div class="recipe-notes">'+esc(r.notes)+'</div>':'')+
      '</div>';
    }).join('');
  }

  function build(){
    var sg=g('lolstsigil');if(sg)sg.innerHTML=sigil(d.region);
    var nm=g('lolstnm');if(nm)nm.textContent=d.name||'—';
    var ln=g('lolstlnbtn');if(ln)ln.textContent=TH?'TH':'EN';
    var ft=g('lolstfoot');if(ft)ft.textContent=T('foot');

    var defs=[
      ['stat',T('stat'),pStat],
      ['skill',T('skill'),pSkills],
      ['items',T('items'),pItems],
      ['gear',T('gear'),pGear],
      ['craft',T('craft'),pCraft],
      ['log',T('log'),pLog]
    ];
    var tabsH='',panesH='',first=null;
    defs.forEach(function(t){
      if(!first)first=t[0];
      var isFirst=(first===t[0]);
      tabsH+='<div class="lolst-tab'+(isFirst?' active':'')+'" data-t="'+t[0]+'">'+esc(t[1])+'</div>';
      panesH+='<div class="lolst-panel'+(isFirst?' active':'')+'" data-p="'+t[0]+'">'+t[2]()+'</div>';
    });
    var tabs=g('lolsttabs');if(tabs)tabs.innerHTML=tabsH;
    var panes=g('lolstpanes');if(panes)panes.innerHTML=panesH;
  }

  build();

  function sendToChat(txt){
    setTimeout(function(){
      try{
        var w=window.parent||window;
        var ta=w.document.getElementById('send_textarea')||w.document.querySelector('textarea.chat-input,#textareaAutosize,textarea');
        if(ta){
          var dd=Object.getOwnPropertyDescriptor(w.HTMLTextAreaElement.prototype,'value');
          if(dd&&dd.set)dd.set.call(ta,txt);else ta.value=txt;
          ta.dispatchEvent(new Event('input',{bubbles:true}));
          setTimeout(function(){try{var sb=w.document.getElementById('send_but');if(sb)sb.click();else ta.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',keyCode:13,bubbles:true}));}catch(e){}},150);
          return;
        }
      }catch(e){}
      try{navigator.clipboard.writeText(txt);}catch(e){}
    },450);
  }

  var whead=g('lolstwhead');
  if(whead)whead.addEventListener('click',function(){win.classList.toggle('closed');});

  var lnbtn=g('lolstlnbtn');
  if(lnbtn)lnbtn.addEventListener('click',function(e){
    e.stopPropagation();
    TH=!TH;sel=[];build();
  });

  var tabs=g('lolsttabs');
  if(tabs)tabs.addEventListener('click',function(e){
    var tab=e.target.closest('.lolst-tab');
    if(!tab)return;
    var t=tab.getAttribute('data-t');
    Array.prototype.forEach.call(tabs.querySelectorAll('.lolst-tab'),function(x){x.classList.toggle('active',x===tab);});
    var panes=g('lolstpanes');
    if(panes)Array.prototype.forEach.call(panes.querySelectorAll('.lolst-panel'),function(p){p.classList.toggle('active',p.getAttribute('data-p')===t);});
  });

  var panes=g('lolstpanes');
  if(panes)panes.addEventListener('click',function(e){
    var pill=e.target.closest('.craft-pill');
    if(pill){
      var idx=parseInt(pill.getAttribute('data-idx'));
      var pos=sel.indexOf(idx);
      if(pos>=0)sel.splice(pos,1);else sel.push(idx);
      pill.classList.toggle('selected',sel.indexOf(idx)>=0);
      var box=panes.querySelector('.craft-sel-box');
      if(box){
        var inv=d.inventory||[];
        var txt=sel.length?sel.map(function(i){var it=inv[i];return it?it.name+' ×'+(it.qty||1):'?';}).join(' + '):T('none');
        box.textContent=txt;
        box.classList.toggle('has-items',sel.length>0);
      }
      return;
    }
    var craft=e.target.closest('.btn-craft');
    if(craft){
      var inv=d.inventory||[];
      if(!sel.length){alert(TH?'เลือกวัตถุดิบก่อน':'Select ingredients first.');return;}
      var intentEl=panes.querySelector('.craft-intent');
      var intent=intentEl?intentEl.value.trim():'';
      if(!intent){alert(TH?'ระบุสิ่งที่ต้องการคราฟ':'Describe what you want to craft.');return;}
      var ingr=sel.map(function(i){var it=inv[i];return it?it.name+' ×'+(it.qty||1):'?';});
      sendToChat('<'+'LOL_CRAFT>'+JSON.stringify({ingredients:ingr,intent:intent})+'<'+'/LOL_CRAFT>');
      sel=[];build();
      return;
    }
    var del=e.target.closest('.btn-del');
    if(del){
      var rid=parseInt(del.getAttribute('data-rid'));
      var rname=del.getAttribute('data-rname');
      sendToChat('<'+'LOL_RECIPE_DELETE>'+JSON.stringify({recipe_id:rid,recipe_name:rname})+'<'+'/LOL_RECIPE_DELETE>');
    }
  });
})();
</script>
</body>
</html>

